import android.content.Context;
import android.content.SharedPreferences;

public class UserCredentialStore {
    private static final String PREFS_NAME = "user_credentials";
    private static final String PREF_USERNAME = "username";
    private static final String PREF_PASSWORD = "password";

    public static void storeCredentials(Context context, String username, String password) {
        SharedPreferences prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE);
        prefs.edit().putString(PREF_USERNAME, username).apply();
        prefs.edit().putString(PREF_PASSWORD, password).apply();
    }

    public static String getUsername(Context context) {
        SharedPreferences prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE);
        return prefs.getString(PREF_USERNAME, "");
    }

    public static String getPassword(Context context) {
        SharedPreferences prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE);
        return prefs.getString(PREF_PASSWORD, "");
    }
}
